package gui

// tokenPackShareHTML is self-contained: opening a bearer share link never
// contacts a third party or borrows the administrator's authenticated assets.
const tokenPackShareHTML = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer"><title>{{.Pack.Name}} · Magpie</title>
<style nonce="{{.Nonce}}">*{box-sizing:border-box}body{margin:0;background:#f6f7f9;color:#17212e;font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:760px;margin:60px auto;padding:28px}.brand{font-size:13px;letter-spacing:.12em;color:#667384}h1{font-size:32px;line-height:1.25;margin:16px 0 8px}p{color:#667384}.card{background:white;border:1px solid #dfe4eb;border-radius:16px;padding:24px;margin-top:24px}.numbers{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.numbers span{display:block;color:#667384;font-size:12px}.numbers strong{font-size:24px;font-variant-numeric:tabular-nums}.field{margin:24px 0 0}.label{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;font-size:13px;font-weight:600}code{display:block;background:#f4f6f9;padding:14px;border-radius:8px;overflow-wrap:anywhere;white-space:pre-wrap;font:13px/1.6 ui-monospace,SFMono-Regular,monospace;user-select:all}button{font:inherit;color:#2459d3;border:1px solid #dbe3f0;background:#fff;padding:5px 12px;border-radius:7px;cursor:pointer}ul{padding-left:20px}small{display:block;margin-top:24px;color:#667384}#copy-status{min-height:24px;color:#2459d3}@media(max-width:520px){main{margin:16px auto;padding:20px}.card{padding:18px}.numbers{grid-template-columns:1fr}.numbers strong{font-size:22px}}</style></head>
<body><main><div class="brand">MAGPIE / TOKEN PACKAGE</div><h1>{{.Pack.Name}}</h1><p>专属模型配置 · 填入支持自定义 API 的客户端即可使用</p>
<section class="card" aria-label="套餐额度"><div class="numbers"><div><span>总额度 · Token</span><strong>{{.Pack.TotalTokens}}</strong></div><div><span>已使用</span><strong>{{.Pack.UsedTokens}}</strong></div><div><span>可用余额</span><strong>{{.Pack.RemainingTokens}}</strong></div></div>{{if .Pack.ReservedTokens}}<p>有 {{.Pack.ReservedTokens}} Token 正在预留中；请求完成或管理员核销后更新。</p>{{end}}</section>
<section class="card" aria-label="API 配置"><div class="field"><div class="label">OpenAI Base URL<button type="button" data-copy="base-url">复制</button></div><code id="base-url">{{.BaseURL}}</code></div><div class="field"><div class="label">Anthropic / Gemini Base URL<button type="button" data-copy="root-url">复制</button></div><code id="root-url">{{.RootURL}}</code></div><div class="field"><div class="label">API Key<button type="button" data-copy="api-key">复制</button></div><code id="api-key">{{.Pack.APIKey}}</code></div><div class="field"><div class="label">可用模型</div><ul>{{range .Pack.Models}}<li><code>{{.}}</code></li>{{end}}</ul></div>{{if .Expiry}}<p>有效期至 {{.Expiry}}</p>{{end}}<p id="copy-status" role="status" aria-live="polite"></p></section>
<small>链接持有者可以查看此套餐的 API Key，请妥善保管。额度按上游报告的输入和输出 Token 计算，包含缓存读取与写入且不重复计数；同一套餐的请求依次执行。中断且无法确认用量的请求需要管理员核销。</small></main>
<script nonce="{{.Nonce}}">document.querySelectorAll('[data-copy]').forEach(function(button){button.addEventListener('click',async function(){var text=document.getElementById(button.dataset.copy).textContent;var status=document.getElementById('copy-status');try{if(!navigator.clipboard)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(text);status.textContent='已复制';}catch(error){var selection=window.getSelection();var range=document.createRange();range.selectNodeContents(document.getElementById(button.dataset.copy));selection.removeAllRanges();selection.addRange(range);status.textContent='请手动复制已选中的内容';}});});</script></body></html>`
